1	use comemo::Track;
2	use smallvec::smallvec;
3	use typst_library::diag::SourceResult;
4	use typst_library::engine::Engine;
5	use typst_library::foundations::{Content, Context, Depth, Packed, Resolve, StyleChain};
6	use typst_library::introspection::Locator;
7	use typst_library::layout::{
8	    Abs, Axes, Dir, Fragment, Frame, FrameItem, Length, Point, Region, Regions, Size,
9	};
10	use typst_library::model::{EnumElem, ListElem, Numbering, ParElem, ParbreakElem};
11	use typst_library::pdf::PdfMarkerTag;
12	use typst_library::text::TextElem;
13	use typst_syntax::Span;
14	
15	use crate::stack::{StackLayoutChild, layout_stack_internal};
16	
17	/// Layout the list.
18	#[typst_macros::time(span = elem.span())]
19	pub fn layout_list(
20	    elem: &Packed<ListElem>,
21	    engine: &mut Engine,
22	    locator: Locator,
23	    styles: StyleChain,
24	    regions: Regions,
25	) -> SourceResult<Fragment> {
26	    let indent = elem.indent.get(styles);
27	    let body_indent = elem.body_indent.get(styles);
28	    let tight = elem.tight.get(styles);
29	    let gutter = elem.spacing.get(styles).unwrap_or_else(|| {
30	        if tight { styles.get(ParElem::leading) } else { styles.get(ParElem::spacing) }
31	    });
32	    let is_rtl = styles.get(TextElem::dir).resolve(styles) == Dir::RTL;
33	
34	    let Depth(depth) = styles.get(ListElem::depth);
35	
36	    // Use the user's preferred vertical alignment. Among other things, it
37	    // avoids '#set align' interference with the list.
38	    let marker_align = elem.marker_align.get(styles);
39	    let baseline_align = marker_align.y().is_none();
40	    let marker = elem
41	        .marker
42	        .get_ref(styles)
43	        .resolve(engine, styles, depth)?
44	        .aligned(marker_align);
45	
46	    let mut items = vec![];
47	    for item in &elem.children {
48	        // Text in wide lists shall always turn into paragraphs.
49	        let mut body = item.body.clone();
50	        if !tight {
51	            body += ParbreakElem::shared();
52	        }
53	        let body = body.set(ListElem::depth, Depth(1));
54	
55	        let item = ItemContent {
56	            marker: PdfMarkerTag::ListItemLabel(marker.clone()),
57	            body: PdfMarkerTag::ListItemBody(body),
58	        };
59	
60	        items.push(item);
61	    }
62	
63	    let layouter = ListLayouter::new(
64	        gutter,
65	        elem.span(),
66	        indent,
67	        body_indent,
68	        baseline_align,
69	        is_rtl,
70	        styles,
71	    );
72	
73	    layout_items(layouter, items, engine, locator, styles, regions)
74	}
