76	/// Layout the enumeration.
77	#[typst_macros::time(span = elem.span())]
78	pub fn layout_enum(
79	    elem: &Packed<EnumElem>,
80	    engine: &mut Engine,
81	    locator: Locator,
82	    styles: StyleChain,
83	    regions: Regions,
84	) -> SourceResult<Fragment> {
85	    let numbering = elem.numbering.get_ref(styles);
86	    let reversed = elem.reversed.get(styles);
87	    let indent = elem.indent.get(styles);
88	    let body_indent = elem.body_indent.get(styles);
89	    let tight = elem.tight.get(styles);
90	    let gutter = elem.spacing.get(styles).unwrap_or_else(|| {
91	        if tight { styles.get(ParElem::leading) } else { styles.get(ParElem::spacing) }
92	    });
93	    let is_rtl = styles.get(TextElem::dir).resolve(styles) == Dir::RTL;
94	
95	    let mut items = vec![];
96	    let mut number = elem
97	        .start
98	        .get(styles)
99	        .unwrap_or_else(|| if reversed { elem.children.len() as u64 } else { 1 });
100	    let mut parents = styles.get_cloned(EnumElem::parents);
101	
102	    let full = elem.full.get(styles);
103	
104	    // Horizontally align based on the given respective parameter.
105	    // Vertically align to the top to avoid inheriting `horizon` or `bottom`
106	    // alignment from the context and having the number be displaced in
107	    // relation to the item it refers to.
108	    let number_align = elem.number_align.get(styles);
109	    let baseline_align = number_align.y().is_none();
110	
111	    for item in &elem.children {
112	        number = item.number.get(styles).unwrap_or(number);
113	
114	        let context = Context::new(None, Some(styles));
115	        let resolved = if full {
116	            parents.push(number);
117	            let content = numbering
118	                .apply(engine, context.track(), item.span(), &parents)?
119	                .display();
120	            parents.pop();
121	            content
122	        } else {
123	            match numbering {
124	                Numbering::Pattern(pattern) => TextElem::packed(pattern.apply_kth(
125	                    engine,
126	                    item.span(),
127	                    parents.len(),
128	                    number,
129	                )),
130	                Numbering::Func(_) => numbering
131	                    .apply(engine, context.track(), item.span(), &[number])?
132	                    .display(),
133	            }
134	        };
135	
136	        // Disable overhang as a workaround to end-aligned dots glitching
137	        // and decreasing spacing between numbers and items.
138	        let resolved = resolved.aligned(number_align).set(TextElem::overhang, false);
139	
140	        // Text in wide enums shall always turn into paragraphs.
141	        let mut body = item.body.clone();
142	        if !tight {
143	            body += ParbreakElem::shared();
144	        }
145	
146	        let body = body.set(EnumElem::parents, smallvec![number]);
147	
148	        let item = ItemContent {
149	            marker: PdfMarkerTag::ListItemLabel(resolved),
150	            body: PdfMarkerTag::ListItemBody(body),
151	        };
152	
153	        items.push(item);
154	        number =
155	            if reversed { number.saturating_sub(1) } else { number.saturating_add(1) };
156	    }
157	
158	    let layouter = ListLayouter::new(
159	        gutter,
160	        elem.span(),
161	        indent,
162	        body_indent,
163	        baseline_align,
164	        is_rtl,
165	        styles,
166	    );
167	
168	    layout_items(layouter, items, engine, locator, styles, regions)
169	}
170	
171	/// Structure with the content for each list item.
172	struct ItemContent {
173	    /// The item marker.
174	    marker: Content,
175	    /// The item body.
176	    body: Content,
177	}
178	
179	/// Layout data shared across all list items.
180	struct ListLayouter {
181	    /// Gutter spacing between items.
182	    gutter: Length,
183	    /// Span of the list/enum element.
184	    span: Span,
185	    /// List indent from the text start.
186	    indent: Abs,
187	    /// Indent between the marker and the body.
188	    body_indent: Abs,
189	    /// Whether baseline alignment should be enabled. When disabled, markers
190	    /// control their own alignment.
191	    baseline_align: bool,
192	    /// Whether RTL was the chosen text direction.
193	    is_rtl: bool,
194	    /// Maximum measured width of a marker, so they may align horizontally
195	    /// relative to each other.
196	    marker_width: Abs,
197	    /// If the list may not expand to fill the whole region (e.g. if `width:
198	    /// auto` was used), then this holds the measured width of an item body, so
199	    /// they may align horizontally relative to each other.
200	    body_width: Option<Abs>,
201	}
202	
203	impl ListLayouter {
204	    /// Create a new list layouter with defaults for values that will be
205	    /// calculated later.
206	    fn new(
207	        gutter: Length,
208	        span: Span,
209	        indent: Length,
210	        body_indent: Length,
211	        baseline_align: bool,
212	        is_rtl: bool,
213	        styles: StyleChain,
214	    ) -> Self {
215	        let indent = indent.resolve(styles);
216	        let body_indent = body_indent.resolve(styles);
217	
218	        Self {
219	            gutter,
220	            span,
221	            indent,
222	            body_indent,
223	            baseline_align,
224	            is_rtl,
225	
226	            // These will be calculated later.
227	            marker_width: Abs::zero(),
228	            body_width: None,
229	        }
230	    }
231	}
232	
233	/// Layout list items.
234	///
235	/// This is done in 4 steps:
236	///
237	/// 1. Compute marker widths for horizontal marker alignment;
238	/// 2. If necessary (when within a `width: auto` block or page), compute body
239	///    widths as well for horizontal body alignment to work;
240	/// 3. Generate list item layouters, each of which is responsible for vertical
241	///    marker alignment (baseline-aligned or not, depending on user settings);
242	/// 4. Pass each list item to the stack layouter. The stack layouter makes it
243	///    possible for them to expand to the full available width, allowing for center
244	///    or right alignment to work within the item body.
245	#[typst_macros::time(span = layouter.span)]
246	fn layout_items(
247	    mut layouter: ListLayouter,
248	    items: Vec<ItemContent>,
249	    engine: &mut Engine,
250	    locator: Locator,
251	    styles: StyleChain,
252	    regions: Regions,
253	) -> SourceResult<Fragment> {
254	    // Store locators used during measuring to ensure the same locators will be
255	    // used later when laying out. This is needed to make introspection work
256	    // properly.
257	    let mut locator = locator.split();
258	    let locators: Vec<_> = items
259	        .iter()
260	        .map(|item| {
261	            let marker_locator = locator.next(&item.marker.span());
262	            let body_locator = locator.next(&item.body.span());
263	            (marker_locator, body_locator)
264	        })
265	        .collect();
266	
267	    layouter.marker_width =
268	        measure_markers(&layouter, &items, &locators, engine, styles, regions)?;
269	
270	    if regions.size.x.to_raw().is_infinite() || !regions.expand.x {
271	        layouter.body_width =
272	            Some(measure_bodies(&layouter, &items, &locators, engine, styles, regions)?);
273	    }
274	
275	    let cells =
276	        items
277	            .iter()
278	            .zip(&locators)
279	            .map(|(item, (marker_locator, body_locator))| {
280	                StackLayoutChild::CustomLayouter(|engine, styles, regions| {
281	                    layout_item(
282	                        item,
283	                        &layouter,
284	                        engine,
285	                        marker_locator,
286	                        body_locator,
287	                        styles,
288	                        regions,
289	                    )
290	                })
291	            });
292	
293	    layout_stack_internal(
294	        cells,
295	        layouter.span,
296	        Some(layouter.gutter.into()),
297	        Dir::TTB,
298	        engine,
299	        // This locator should not be used by cells.
300	        locator.next(&()),
301	        styles,
302	        regions,
303	    )
304	}
305	
306	/// Measure marker.
307	fn measure_markers<'a>(
308	    list: &ListLayouter,
309	    items: &[ItemContent],
310	    locators: &[(Locator<'a>, Locator<'a>)],
311	    engine: &mut Engine,
312	    styles: StyleChain,
313	    regions: Regions,
314	) -> SourceResult<Abs> {
315	    let available_width = regions.size.x - list.indent - list.body_indent;
316	
317	    // Measure markers, so we can align them horizontally relative to the
318	    // largest width.
319	    let mut marker_width = Abs::zero();
320	    for (item, (marker_locator, _)) in items.iter().zip(locators) {
321	        let marker = crate::layout_frame(
322	            engine,
323	            &item.marker,
324	            marker_locator.relayout(),
325	            styles,
326	            Region::new(Axes::new(available_width, Abs::inf()), Axes::splat(false)),
327	        )?;
328	        marker_width.set_max(marker.width());
329	    }
330	
331	    // Redistribute width if necessary. It is okay to do this before measuring
332	    // the body (thus effectively checking for the width in two places) since a
333	    // non-zero-width body would cause an overlarge marker to surpass page width
334	    // regardless. That is, this check doesn't affect the semantics of the other
335	    // check, but it is necessary in case we don't measure the body at all.
336	    Ok(marker_width.min(available_width))
337	}
338	
339	/// Infinite space or `width: auto` used. Both would prevent the list from
340	/// expanding to fit, breaking alignment. Therefore, restrict the list size to
341	/// the size of the largest item, prompting list items to align between
342	/// themselves instead of relative to the full page width.
343	fn measure_bodies(
344	    list: &ListLayouter,
345	    items: &[ItemContent],
346	    locators: &[(Locator, Locator)],
347	    engine: &mut Engine,
348	    styles: StyleChain,
349	    regions: Regions,
350	) -> SourceResult<Abs> {
351	    let available_width = regions.size.x - list.indent - list.body_indent;
352	    let mut measured_body_width = Abs::zero();
353	    for (item, (_, body_locator)) in items.iter().zip(locators) {
354	        let body = crate::layout_frame(
355	            engine,
356	            &item.body,
357	            body_locator.relayout(),
358	            styles,
359	            Region::new(Axes::new(available_width, Abs::inf()), Axes::splat(false)),
360	        )?;
361	        measured_body_width.set_max(body.width());
362	    }
363	
364	    // If marker and body together exceed the page width, the marker gets the
365	    // space it requested and the body the rest. This makes some sense since the
366	    // marker comes first, is unlikely to be large, and is unlikely to be able
367	    // to wrap. It also keeps consistency between the case where we measure the
368	    // body and the case where we don't.
369	    Ok(measured_body_width.min(available_width - list.marker_width))
370	}
371	
372	/// Layout the item, with support for vertical marker alignment.
373	#[typst_macros::time(span = item.body.span())]
374	fn layout_item(
375	    item: &ItemContent,
376	    list: &ListLayouter,
377	    engine: &mut Engine,
378	    marker_locator: &Locator,
379	    body_locator: &Locator,
380	    styles: StyleChain,
381	    regions: Regions,
382	) -> SourceResult<Fragment> {
383	    let mut layouter =
384	        ItemLayouter::new(item, list, marker_locator, body_locator, styles, regions);
385	
386	    let mut marker = layouter.layout_marker(
387	        Region::new(
388	            Axes::new(list.marker_width, regions.base().y),
389	            Axes::new(true, false),
390	        ),
391	        engine,
392	    )?;
393	
394	    let mut body = layouter.layout_body(layouter.body_regions, engine)?;
395	
396	    if layouter.list.baseline_align {
397	        layouter.baseline_align(&marker, &mut body, engine)?;
398	    } else {
399	        layouter.vertical_align(&mut marker, &body, engine)?;
400	    }
401	
402	    layouter.finish(marker, body)
403	}
404	
405	/// Layout data for a specific item.
406	///
407	/// Its methods assume only `layout_marker` and `layout_body` are used to layout
408	/// the item's contents.
409	struct ItemLayouter<'a> {
410	    /// Item content to layout.
411	    item: &'a ItemContent,
412	    /// List-wide layout data.
413	    list: &'a ListLayouter,
414	    /// Locator used to measure and layout the marker (must be the same to avoid
415	    /// introspection bugs).
416	    marker_locator: &'a Locator<'a>,
417	    /// Locator used to measure and layout the body (must be the same to avoid
418	    /// introspection bugs).
419	    body_locator: &'a Locator<'a>,
420	    /// Stylechain at this item's location.
421	    styles: StyleChain<'a>,
422	    /// The first body's non-empty frame.
423	    first_frame: usize,
424	    /// The item's regions, but adapted for the body's expected width.
425	    body_regions: Regions<'a>,
426	    /// Total body indent from the left of the region, as well as its offset
427	    /// from the top of the region.
428	    ///
429	    /// Vertical offset is always zero without baseline alignment.
430	    body_offset: Point,
431	    /// Resolved marker indent from the left of the region, as well as its
432	    /// offset from the top of the region.
433	    ///
434	    /// Vertical offset is always zero without baseline alignment.
435	    marker_offset: Point,
436	}
437	
438	impl<'a> ItemLayouter<'a> {
439	    /// Begin item layout by resolving default values of attributes.
440	    fn new(
441	        item: &'a ItemContent,
442	        list: &'a ListLayouter,
443	        marker_locator: &'a Locator<'a>,
444	        body_locator: &'a Locator<'a>,
445	        styles: StyleChain<'a>,
446	        regions: Regions<'a>,
447	    ) -> Self {
448	        let total_body_indent = list.indent + list.marker_width + list.body_indent;
449	
450	        // Restrict the body to the available space.
451	        let mut body_regions = regions;
452	        if let Some(body_width) = list.body_width {
453	            body_regions.size.x = body_width;
454	            body_regions.expand.x = true;
455	        } else {
456	            body_regions.size.x -= total_body_indent;
457	        }
458	
459	        Self {
460	            item,
461	            list,
462	            marker_locator,
463	            body_locator,
464	            styles,
465	            first_frame: 0,
466	            body_regions,
467	            body_offset: Point::with_x(total_body_indent),
468	            marker_offset: Point::with_x(list.indent),
469	        }
470	    }
471	
472	    /// Layout the list marker with the given region data.
473	    fn layout_marker(&self, region: Region, engine: &mut Engine) -> SourceResult<Frame> {
474	        crate::layout_frame(
475	            engine,
476	            &self.item.marker,
477	            self.marker_locator.relayout(),
478	            self.styles,
479	            region,
480	        )
481	    }
482	
483	    /// Layout the list body with the given region data.
484	    fn layout_body(
485	        &mut self,
486	        regions: Regions,
487	        engine: &mut Engine,
488	    ) -> SourceResult<Fragment> {
489	        let fragment = crate::layout_fragment(
490	            engine,
491	            &self.item.body,
492	            self.body_locator.relayout(),
493	            self.styles,
494	            regions,
495	        )?;
496	
497	        // Update the first non-empty frame (ignoring a frame with only tags due
498	        // to a forced region break). If the first frame is not virtually empty,
499	        // then keep the default of 0.
500	        if should_skip_first_frame(&fragment) {
501	            self.first_frame = 1;
502	        }
503	
504	        Ok(fragment)
505	    }
506	
507	    /// Ensure baselines are aligned by either increasing the marker's offset,
508	    /// if the marker is above the body and should thus be moved down, or by both
509	    /// increasing the body's offset and relayouting it with less space, if the
510	    /// body is above the marker.
511	    fn baseline_align(
512	        &mut self,
513	        marker: &Frame,
514	        body_fragment: &mut Fragment,
515	        engine: &mut Engine,
516	    ) -> SourceResult<()> {
517	        // Difference between marker and body baselines, for alignment. A
518	        // positive 'diff' means that the marker is above and must move down,
519	        // whereas a negative 'diff' means that the marker is below, so the body
520	        // must be moved down instead.
521	        let diff = if marker.has_baseline()
522	            && let Some(first) = body_fragment.as_slice().get(self.first_frame)
523	            && first.has_baseline()
524	        {
525	            first.baseline() - marker.baseline()
526	        } else {
527	            // One of the frames has no natural baseline, so baseline alignment
528	            // is disabled.
529	            Abs::zero()
530	        };
531	
532	        if diff >= Abs::zero() {
533	            // Marker's baseline is above the body's baseline, so we can align
534	            // them by moving the baseline downwards, without moving the body.
535	            self.marker_offset.y = diff;
536	        } else {
537	            // Marker's baseline is below the body's baseline, so move the body
538	            // down to avoid overflowing the marker into something above the
539	            // list (item).
540	            //
541	            // To do this, we layout the body again but with '-diff' less space
542	            // (that is, '+diff' more space, as it is negative), and then move
543	            // the result '-diff' units downwards. Of course, this could
544	            // theoretically generate a new result that is even worse - but
545	            // there is only so much we can do with a finite number of
546	            // iterations.
547	            let mut regions = self.body_regions;
548	            regions.size.y += diff;
549	            *body_fragment = self.layout_body(regions, engine)?;
550	
551	            self.body_offset.y = -diff;
552	        }
553	
554	        Ok(())
555	    }
556	
557	    /// Called when explicit marker alignment was specified. Re-layout the
558	    /// marker with the same height as the body's first frame so it may align
559	    /// itself vertically with the body.
560	    fn vertical_align(
561	        &mut self,
562	        marker: &mut Frame,
563	        body: &Fragment,
564	        engine: &mut Engine,
565	    ) -> SourceResult<()> {
566	        // 'Measuring' the height of an 'auto row'.
567	        let height = if let Some(body_first) = body.as_slice().get(self.first_frame) {
568	            // Don't align if the body is too short.
569	            body_first.height().max(marker.height())
570	        } else {
571	            // Body appears to be fully empty, so the marker should not align.
572	            marker.height()
573	        };
574	
575	        let region =
576	            Region::new(Axes::new(self.list.marker_width, height), Axes::splat(true));
577	
578	        *marker = self.layout_marker(region, engine)?;
579	        Ok(())
580	    }
581	
582	    /// Finish list item layout by indenting the body's frames and add the
583	    /// marker to the first non-empty frame.
584	    fn finish(&self, marker: Frame, body_fragment: Fragment) -> SourceResult<Fragment> {
585	        // Collect the item's frames. Here, we add the marker to the first
586	        // non-empty frame, and additionally indent the whole body so it appears
587	        // after the marker.
588	        let mut frames = vec![];
589	        for (i, body_frame) in body_fragment.into_iter().enumerate() {
590	            let width = self.body_offset.x + body_frame.width();
591	
592	            let mut height = body_frame.height() + self.body_offset.y;
593	            if i == self.first_frame {
594	                // Also consider the marker height, but only for the frame into
595	                // which it will be placed.
596	                height.set_max(marker.height() + self.marker_offset.y);
597	            }
598	
599	            let mut frame = Frame::soft(Size::new(width, height));
600	
601	            let mut body_pos = self.body_offset;
602	            if self.list.is_rtl {
603	                // In RTL, items expand to the left, thus the position must
604	                // additionally be offset by the full width. However, since the
605	                // body is always at the end, it will expand to the right in
606	                // LTR, and therefore to the left in RTL. That is, its leftmost
607	                // corner must be at the left of the frame, since it now expands
608	                // to the left.
609	                //
610	                // Or, mathematically:
611	                // body_pos.x = width - (body_frame.width() + body_pos.x)
612	                //            = self.body_offset.x + body_frame.width() -
613	                //                  - (body_frame.width() + self.body_offset.x)
614	                //            = 0.
615	                body_pos.x = Abs::zero();
616	            }
617	
618	            // Only place the marker on the first non-empty frame.
619	            if i == self.first_frame {
620	                let mut marker_pos = self.marker_offset;
621	                if self.list.is_rtl {
622	                    marker_pos.x = width - (self.list.marker_width + marker_pos.x);
623	                }
624	                frame.push_frame(marker_pos, marker.clone());
625	            }
626	
627	            frame.push_frame(body_pos, body_frame);
628	            frames.push(frame);
629	        }
630	
631	        Ok(Fragment::frames(frames))
632	    }
633	}
634	
635	/// Check whether the first frame is essentially empty (only contains tags).
636	/// This usually indicates a forced region break, which we should ignore.
637	fn should_skip_first_frame(fragment: &Fragment) -> bool {
638	    fragment.len() > 1
639	        && is_empty_frame(&fragment.as_slice()[0])
640	        && fragment.iter().skip(1).any(|f| !is_empty_frame(f))
641	}
642	
643	/// Check if a frame is empty (taken from grid layouting).
644	///
645	/// HACK: Also consider frames empty if they only contain tags. Table
646	/// and grid cells need to be locatable for pdf accessibility, but
647	/// the introspection tags interfere with the layouting.
648	fn is_empty_frame(frame: &Frame) -> bool {
649	    frame.items().all(|(_, item)| matches!(item, FrameItem::Tag(_)))
650	}
651

