197	    /// Add spacing along the spacing direction.
198	    fn layout_spacing(&mut self, spacing: Spacing) {
199	        match spacing {
200	            Spacing::Rel(v) => {
201	                // Resolve the spacing and limit it to the remaining space.
202	                let resolved = v
203	                    .resolve(self.styles)
204	                    .relative_to(self.regions.base().get(self.axis));
205	                let remaining = self.regions.size.get_mut(self.axis);
206	                let limited = resolved.min(*remaining);
207	                if self.dir.axis() == Axis::Y {
208	                    *remaining -= limited;
209	                }
210	                self.used.main += limited;
211	                self.items.push(StackItem::Absolute(resolved));
212	            }
213	            Spacing::Fr(v) => {
214	                self.fr += v;
215	                self.items.push(StackItem::Fractional(v));
216	            }
217	        }
218	    }
