220	    /// Layout an arbitrary block.
221	    fn layout_block(
222	        &mut self,
223	        engine: &mut Engine,
224	        block: &Content,
225	        styles: StyleChain,
226	    ) -> SourceResult<()> {
227	        if self.regions.is_full() {
228	            self.finish_region()?;
229	        }
230	
231	        // Block-axis alignment of the `AlignElem` is respected by stacks.
232	        let align = if let Some(align) = block.to_packed::<AlignElem>() {
233	            align.alignment.get(styles)
234	        } else if let Some(styled) = block.to_packed::<StyledElem>() {
235	            styles.chain(&styled.styles).get(AlignElem::alignment)
236	        } else {
237	            styles.get(AlignElem::alignment)
238	        }
239	        .resolve(styles);
240	
241	        let fragment = crate::layout_fragment(
242	            engine,
243	            block,
244	            self.locator.next(&block.span()),
245	            styles,
246	            self.regions,
247	        )?;
248	
249	        self.layout_fragment(align, fragment)
250	    }
251	
252	    /// Layout a child with a custom layouter procedure.
253	    fn layout_custom_layouter(
254	        &mut self,
255	        engine: &mut Engine,
256	        layouter: impl Fn(&mut Engine, StyleChain, Regions) -> SourceResult<Fragment>,
257	        styles: StyleChain,
258	    ) -> SourceResult<()> {
259	        if self.regions.is_full() {
260	            self.finish_region()?;
261	        }
262	
263	        let align = styles.get(AlignElem::alignment).resolve(styles);
264	
265	        let fragment = layouter(engine, styles, self.regions)?;
266	
267	        self.layout_fragment(align, fragment)
268	    }
269	
270	    /// Store laid out content, coming from either a block or a custom layouter.
271	    fn layout_fragment(
272	        &mut self,
273	        align: Axes<FixedAlignment>,
274	        fragment: Fragment,
275	    ) -> SourceResult<()> {
276	        let len = fragment.len();
277	        for (i, frame) in fragment.into_iter().enumerate() {
278	            // Grow our size, shrink the region and save the frame for later.
279	            let specific_size = frame.size();
280	            if self.dir.axis() == Axis::Y {
281	                self.regions.size.y -= specific_size.y;
282	            }
283	
284	            let generic_size = match self.axis {
285	                Axis::X => GenericSize::new(specific_size.y, specific_size.x),
286	                Axis::Y => GenericSize::new(specific_size.x, specific_size.y),
287	            };
288	
289	            self.used.main += generic_size.main;
290	            self.used.cross.set_max(generic_size.cross);
291	
292	            self.items.push(StackItem::Frame(frame, align));
293	
294	            if i + 1 < len {
295	                self.finish_region()?;
296	            }
297	        }
298	
299	        Ok(())
300	    }
301	
302	    /// Advance to the next region.
303	    fn finish_region(&mut self) -> SourceResult<()> {
304	        // Determine the size of the stack in this region depending on whether
305	        // the region expands.
306	        let mut size = self
307	            .expand
308	            .select(self.initial, self.used.into_axes(self.axis))
309	            .min(self.initial);
310	
311	        // Expand fully if there are fr spacings.
312	        let full = self.initial.get(self.axis);
313	        let remaining = full - self.used.main;
314	        if self.fr.get() > 0.0 && full.is_finite() {
315	            self.used.main = full;
316	            size.set(self.axis, full);
317	        }
318	
319	        if !size.is_finite() {
320	            bail!(self.span, "stack spacing is infinite");
321	        }
322	
323	        let mut output = Frame::soft(size);
324	        let mut cursor = Abs::zero();
325	        let mut ruler: FixedAlignment = self.dir.start().into();
326	
327	        // Place all frames.
328	        for item in self.items.drain(..) {
329	            match item {
330	                StackItem::Absolute(v) => cursor += v,
331	                StackItem::Fractional(v) => cursor += v.share(self.fr, remaining),
332	                StackItem::Frame(frame, align) => {
333	                    if self.dir.is_positive() {
334	                        ruler = ruler.max(align.get(self.axis));
335	                    } else {
336	                        ruler = ruler.min(align.get(self.axis));
337	                    }
338	
339	                    // Align along the main axis.
340	                    let parent = size.get(self.axis);
341	                    let child = frame.size().get(self.axis);
342	                    let main = ruler.position(parent - self.used.main)
343	                        + if self.dir.is_positive() {
344	                            cursor
345	                        } else {
346	                            self.used.main - child - cursor
347	                        };
348	
349	                    // Align along the cross axis.
350	                    let other = self.axis.other();
351	                    let cross = align
352	                        .get(other)
353	                        .position(size.get(other) - frame.size().get(other));
354	
355	                    let pos = GenericSize::new(cross, main).to_point(self.axis);
356	                    cursor += child;
357	                    output.push_frame(pos, frame);
358	                }
359	            }
360	        }
361	
362	        // Advance to the next region.
363	        self.regions.next();
364	        self.initial = self.regions.size;
365	        self.used = GenericSize::zero();
366	        self.fr = Fr::zero();
367	        self.finished.push(output);
368	
369	        Ok(())
370	    }
371	
372	    /// Finish layouting and return the resulting frames.
373	    fn finish(mut self) -> SourceResult<Fragment> {
374	        self.finish_region()?;
375	        Ok(Fragment::frames(self.finished))
